from pathlib import Path
from copy import deepcopy
import json
import math
import numpy as np

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'stereo-course/merzlyak-10-base/lessons'
OUT.mkdir(parents=True, exist_ok=True)
WRITTEN = []
COVERAGE = []

def vec(x): return np.array(x, dtype=float)
def lerp(a,b,t): return ((1-t)*vec(a)+t*vec(b)).tolist()
def addpoint(m,name,p): m['points'][name]=[round(float(v),9) for v in p]; return name
def at(m,name,a,b,t): return addpoint(m,name,lerp(m['points'][a],m['points'][b],t))
def line_hit(m,name,a,b,c,d):
    A,B,C,D=(vec(m['points'][x]) for x in (a,b,c,d))
    mat=np.column_stack((B-A,-(D-C)))
    ts,res,rank,_=np.linalg.lstsq(mat,C-A,rcond=None)
    assert rank==2 and np.linalg.norm(A+ts[0]*(B-A)-C-ts[1]*(D-C))<1e-7,(name,a,b,c,d)
    return addpoint(m,name,A+ts[0]*(B-A))
def model(points,edges,faces=(),labels=None,planar=False):
    return {'points':deepcopy(points),'edges':[list(e) for e in edges],'faces':[list(f) for f in faces],
      'labelNames':list(points)[:8] if labels is None else labels,
      'views':{'neutral':{'label':'Исходная конфигурация. Найдите данные точки и грани.'}},'planar':planar}
def cube():
    P={'A':[-1,-1,0],'B':[-1,1,0],'C':[1,1,0],'D':[1,-1,0],
       'A1':[-1,-1,2],'B1':[-1,1,2],'C1':[1,1,2],'D1':[1,-1,2]}
    F=[['A','B','C','D'],['A1','B1','C1','D1'],['A','B','B1','A1'],['B','C','C1','B1'],['C','D','D1','C1'],['D','A','A1','D1']]
    E=[['A','B'],['B','C'],['C','D'],['D','A'],['A1','B1'],['B1','C1'],['C1','D1'],['D1','A1'],['A','A1'],['B','B1'],['C','C1'],['D','D1']]
    return model(P,E,F)
def tetra(apex='S'):
    P={'A':[-2,-1,0],'B':[0,2,0],'C':[2,-1,0],apex:[0,0,3]}
    E=[['A','B'],['B','C'],['C','A'],['A',apex],['B',apex],['C',apex]]
    F=[['A','B','C'],['A','B',apex],['B','C',apex],['C','A',apex]]
    return model(P,E,F)
def pyramid(apex='S',pentagon=False):
    P={'A':[-2,-1,0],'B':[-1,1,0],'C':[1,1,0],'D':[1.8,-1,0],apex:[0,0,3]}
    base=['A','B','C','D']
    if pentagon:
        P={'A':[-2,-.5,0],'B':[-1,1,0],'C':[1,1,0],'D':[2,-.5,0],'E':[0,-2,0],apex:[0,0,3]}
        base=['A','B','C','D','E']
    E=[[base[i],base[(i+1)%len(base)]] for i in range(len(base))]+[[a,apex] for a in base]
    F=[base]+[[base[i],base[(i+1)%len(base)],apex] for i in range(len(base))]
    return model(P,E,F)
def prism(tri=True):
    base={'A':[-2,-1,0],'B':[0,2,0],'C':[2,-1,0]} if tri else {'A':[-2,-1,0],'B':[-1,1,0],'C':[1,1,0],'D':[1.8,-1,0]}
    names=list(base);P=deepcopy(base)
    for n in names: P[n+'1']=lerp(P[n],vec(P[n])+[.45,.2,3],1)
    E=[[n,n+'1'] for n in names]
    F=[names,[n+'1' for n in names]]
    for i,a in enumerate(names):
        b=names[(i+1)%len(names)];E.extend([[a,b],[a+'1',b+'1']]);F.append([a,b,b+'1',a+'1'])
    return model(P,E,F)
def view(m,key,label,segments=(),polygon=(),points=()):
    v={'label':label}
    if segments:v['segments']=[list(x) for x in segments]
    if polygon:v['polygon']=list(polygon)
    if points:v['points']=list(points)
    m['views'][key]=v
    return key
def section(m,three,naming):
    a,b,c=(vec(m['points'][x]) for x in three);normal=np.cross(b-a,c-a)
    assert np.linalg.norm(normal)>1e-8
    names=[]
    for u,v in m['edges']:
        x,y=vec(m['points'][u]),vec(m['points'][v]);sx,sy=np.dot(normal,x-a),np.dot(normal,y-a)
        hits=[]
        if abs(sx)<1e-8:hits.append((u,x))
        if abs(sy)<1e-8:hits.append((v,y))
        if sx*sy < -1e-10:
            p=x+(y-x)*sx/(sx-sy)
            found=next((n for n,q in m['points'].items() if np.linalg.norm(vec(q)-p)<1e-7),None)
            name=found or naming.get(frozenset([u,v]))
            assert name,('missing-section-name',u,v,p)
            if not found:addpoint(m,name,p)
            hits.append((name,p))
        for name,p in hits:
            if name not in names:names.append(name)
    center=sum((vec(m['points'][n]) for n in names))/len(names)
    axis=vec(m['points'][names[0]])-center;axis/=np.linalg.norm(axis)
    norm=normal/np.linalg.norm(normal);other=np.cross(norm,axis)
    names.sort(key=lambda n:math.atan2(np.dot(vec(m['points'][n])-center,other),np.dot(vec(m['points'][n])-center,axis)))
    view(m,'section','Построенное сечение: '+''.join(names),polygon=names)
    return names
def J(text,kind='theorem'):return {'kind':kind,'text':text}
COMMON='Две общие точки определяют прямую пересечения двух различных плоскостей. В каждой грани сечение идёт по прямой.'
def step(title,prompt,text,v=None,why=COMMON):
    s={'title':title,'prompt':prompt,'explanation':text,'justifications':[J(why)]}
    if v:s['view']=v
    return s
def save(group,n,title,statement,goal,m,steps,helptext,*,caption=None,sourceparts=None,issue=None):
    id=f'research-{group}-{n:03d}';page=30 if group=='sections' else 142
    source={'bookId':'merzlyak-2022-10-base','collection':'research','exercise':f'{group}-{n}','printedPages':[page],'pdfPages':[page+1],'chapter':'Дополнительные задачи'}
    for i,s in enumerate(steps,1):s['id']=f'step-{i}'
    neutral=m.pop('labelNames',[]);m['labelNames']=[]
    if neutral:m['views']['neutral']['points']=neutral
    d={'schemaVersion':1,'revision':1,'id':id,'kind':'exercise','title':('Метод сечений' if group=='sections' else 'Скрещивающиеся прямые')+f' · {n}. '+title,'status':'draft','source':source,
       'statement':{'text':statement,'goal':goal},'visualization':{'type':'scene3d','caption':caption or 'Точная иллюстративная конфигурация. Размеры выбраны для наглядности; выводы обосновываются в шагах. Вспомогательные прямые при необходимости продолжаются.','model':m},
       'help':[{'id':'help-1','question':'С чего начать?','text':helptext}],'steps':steps,
       'answer':{'mode':'manual','prompt':'Запишите построение или доказательство. Сверьте рассуждение с шагами; доказательство автоматически не оценивается.'},'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
    (OUT/(id+'.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');WRITTEN.append(id)
    entry={'sourceId':f'source-research-{group}-{n}','source':source,'requiredParts':[None],'lessonIds':[id],'sourceSubparts':sourceparts or [],'subpartsIncludedTogether':True,'sourcePageScope':'complete_exercise_page','statementVisuallyChecked':True,'solutionStatus':'authored_draft','independentReview':'pending'}
    if issue:entry['sourceIssue']=issue
    COVERAGE.append(entry)

def unit_prism(c=1,d=1):
    m=cube();m['points']={'A':[0,0,0],'B':[1,0,0],'C':[c,d,0],'D':[0,1,0],'A1':[0,0,1],'B1':[1,0,1],'C1':[c,d,1],'D1':[0,1,1]};return m

def foot(m,name,p,a,b):
    P,A,B=(vec(m['points'][x]) for x in (p,a,b));return addpoint(m,name,A+np.dot(P-A,B-A)/np.dot(B-A,B-A)*(B-A))

# Method of sections 1: concurrency is a common trace on BD.
m=tetra('D');at(m,'M','A','D',.6);at(m,'N','A','C',.4);at(m,'K','C','B',.45)
line_hit(m,'X','N','M','C','D');line_hit(m,'Y','N','K','A','B');line_hit(m,'Z','X','K','B','D')
m['labelNames']=['A','B','C','D','M','N','K'];view(m,'traces','Две прямые в плоскости MNK',segments=[['M','X'],['K','Y']],points=['N']);view(m,'bcd','След XK в BCD',polygon=['B','C','D'],segments=[['X','K']],points=['Z']);view(m,'abd','Общая точка Z',segments=[['B','D'],['M','Y'],['K','X']],points=['Z'])
save('sections',1,'Три прямые через одну точку','На рёбрах AD, AC и CB тетраэдра DABC отмечены M, N и K. Пусть X = NM ∩ CD, Y = NK ∩ AB. Докажите, что XK, MY и BD проходят через одну точку.','Обосновать общий след секущей плоскости.',m,[
 step('Одна секущая плоскость','Какая плоскость содержит X и Y?','Плоскость α = MNK содержит прямые MN и NK, значит, содержит X и Y. Поэтому XK и MY лежат в α.','traces'),
 step('Существование пересечения с BD','Почему α пересекает ребро BD?','В грани ACD прямая MN отсекает вершину A от C и D: C и D по одну сторону α. В грани ABC точки N и K лежат на AC и CB, поэтому A и B оказываются по другую сторону α от C. Значит, B и D находятся по разные стороны α; отрезок BD пересекает её в единственной точке Z.','bcd','Плоскость разделяет пространство на два полупространства; отрезок между их точками пересекает плоскость.'),
 step('Два следа через Z','В каких гранях лежат XK и MY?','В BCD линия α∩BCD — XK; в ABD линия α∩ABD — MY. Точка Z лежит в обеих гранях и в α, поэтому Z∈XK и Z∈MY. Все три прямые пересекаются в Z.','abd')],
 'Рассмотрите плоскость MNK и её следы на гранях BCD и ABD. Какую роль играет их общее ребро BD?')

