at(m,'K','B','C',.5);at(m,'E','A','K',.5);at(m,'F','D','K',.5);addpoint(m,'G',(vec(m['points']['A'])+vec(m['points']['B'])+vec(m['points']['D']))/3);at(m,'U','A','D',.5);at(m,'P','A','B',1/3);at(m,'Q','D','B',1/3);at(m,'L','B','K',.5)
view(m,'parallel','EF параллельна AD',segments=[['E','F'],['A','D']],points=['K']);view(m,'centroid','Через G проводим PQ параллельно AD',segments=[['B','U'],['P','Q']],points=['G']);view(m,'base','Доказываем, что P,E,C лежат на одной прямой',segments=[['A','K'],['C','P'],['E','L']],points=['B']);view(m,'section','Сечение CPQ',polygon=['C','P','Q'],points=['E','F','G']);m['labelNames']=['A','B','C','D','K','E','F','G']
save('sections',6,'Сечение проходит через вершину','K — середина BC тетраэдра DABC. Плоскость проведена через центр тяжести G грани ABD и середины E и F отрезков AK и DK. Постройте сечение и найдите расстояние от A до точки пересечения секущей плоскости с прямой AC, если AC=12 см.','Построить сечение и определить точку на AC.',m,[
 step('Параллельное направление','Что представляет EF в треугольнике AKD?','EF соединяет середины AK и DK, поэтому EF∥AD. Секущая плоскость содержит направление AD.','parallel','Средняя линия треугольника параллельна его третьей стороне.'),
 step('След на ABD','Проведите через G прямую PQ∥AD, где P∈AB,Q∈BD.','Пусть U — середина AD. Центроид G лежит на BU и BG:GU=2:1. По подобию BP/BA=BQ/BD=BG/BU=2/3. Значит, AP=AB/3.','centroid','Центр тяжести делит медиану в отношении 2:1 от вершины; подобие треугольников.'),
 step('Проверим точку C','Докажите, что P,E,C коллинеарны.','Возьмите L — середину BK. В треугольнике ABK отрезок EL — средняя линия: EL∥AB и EL=AB/2. Пусть CE пересекает AB в P′. Так как BC=2BK и CL=3BK/2, подобие треугольников CLE и CBP′ даёт BP′=(BC/CL)·EL=2AB/3. Поэтому P′=P и E∈CP.','base','Средняя линия и подобие треугольников.'),
 step('Сечение и расстояние','Какая точка прямой AC лежит в найденном сечении?','C лежит на PE и потому принадлежит секущей плоскости. Контур — треугольник CPQ; F находится на CQ, G — на PQ. A не лежит в этой плоскости, поэтому её единственная точка на AC — C. Искомое расстояние равно AC=12 см.','section')],
 'В треугольнике AKD отрезок EF — средняя линия. Проведите через G параллель к AD и найдите её пересечения с AB и BD.')

