save('skew-lines',1,'Угол между диагоналями','В кубе ABCDA₁B₁C₁D₁ найдите угол между прямыми AC₁ и A₁B.','Найти угол между скрещивающимися прямыми.',m,[
 step('Диагонали квадратной грани','Обозначьте через O центр грани ABB₁A₁.','Диагонали A₁B и AB₁ квадратной грани перпендикулярны и пересекаются в O.','lines','Диагонали квадрата взаимно перпендикулярны.'),
 step('Второе направление','Проведите через O прямую OH∥BC.','BC перпендикулярна грани ABB₁A₁. Поэтому OH⊥A₁B. Прямые AB₁ и OH пересекаются в O и лежат в плоскости AB₁C₁.','perp','Прямая, перпендикулярная плоскости, перпендикулярна всем направлениям этой плоскости.'),
 step('Искомый угол','Где лежит AC₁?','A₁B перпендикулярна двум пересекающимся прямым плоскости AB₁C₁, следовательно, перпендикулярна этой плоскости. Прямая AC₁ лежит в ней, поэтому угол между AC₁ и A₁B равен 90°.','plane','Признак перпендикулярности прямой и плоскости.')],
 'Покажите, что A₁B перпендикулярна плоскости AB₁C₁, содержащей AC₁.')

# 2: a plane through one line and parallel to the other gives a counterexample.
m=model({'A':[-2,0,0],'B':[2,0,0],'C':[0,-1,1.5],'D':[0,2,1.5],'P':[.5,1,0],'Q':[1,0,0],'U':[-2,-1,0],'V':[2,-1,0],'W':[2,2,0],'T':[-2,2,0]},[['A','B'],['C','D']]);m['labelNames']=['A','B','C','D','P'];m['labels']={'A':'a','C':'b'};view(m,'plane','Плоскость α через a, параллельная b',polygon=['U','V','W','T'],points=['P']);view(m,'candidate','Любая секущая через P и Q∈a остаётся в α',segments=[['P','Q']],polygon=['U','V','W','T'])
save('skew-lines',2,'Прямая существует не через каждую точку','Верно ли, что через каждую точку пространства можно провести прямую, пересекающую две данные скрещивающиеся прямые?','Построить и объяснить контрпример.',m,[
 step('Плоскость, не пересекающая b','Проведите через прямую a плоскость α, параллельную b.','Такая плоскость содержит a и направление b. Прямая b не лежит в α, иначе a и b были бы компланарны. Поэтому b∥α и общих точек у них нет.','plane','Через прямую можно провести плоскость, параллельную направлению другой непараллельной прямой.'),
 step('Выберите точку','Возьмите P∈α, но P∉a.','Если прямая через P пересекает a в Q, то P и Q — две различные точки α. Поэтому вся прямая PQ лежит в α.','candidate','Прямая через две точки плоскости целиком лежит в ней.'),
 step('Контрпример','Может ли такая PQ встретить b?','Нет: b не имеет точек в α. Следовательно, через выбранную P нельзя провести прямую, пересекающую обе a и b. Ответ: неверно.','plane','Один допустимый контрпример опровергает утверждение «для каждой точки».')],
 'Выберите точку в плоскости через одну данную прямую, параллельной другой.')

# 3: construct the unique transversal parallel to the third direction.
m=model({'A':[-2,0,0],'B':[2,0,0],'C':[0,-1,2],'D':[0,2,2],'E':[1.5,1,-.5],'F':[1.5,1,2.5],'P':[0,0,0],'Q':[0,0,2],'U':[-2,0,-.5],'V':[2,0,-.5],'W':[2,0,2.5],'T':[-2,0,2.5]},[['A','B'],['C','D'],['E','F']]);m['labelNames']=['A','C','E'];m['labels']={'A':'a','C':'b','E':'c'};view(m,'plane','Плоскость α через a, параллельная c',polygon=['U','V','W','T'],points=['Q']);view(m,'line','Искомая прямая PQ',segments=[['P','Q'],['E','F']],points=['P','Q']);view(m,'unique','Q=b∩α определена единственно',segments=[['C','D'],['P','Q']],points=['Q'])
save('skew-lines',3,'Единственная секущая заданного направления','Три попарно скрещивающиеся прямые a,b,c не параллельны одной плоскости. Докажите: 1) существует прямая, пересекающая a и b и параллельная c; 2) она единственна.','Доказать существование и единственность.',m,[
 step('Выбор плоскости','Проведите α через a параллельно c.','Направления a и c различны, поэтому они задают плоскость α однозначно. Направление b не параллельно α: иначе все три направления были бы параллельны одной плоскости, вопреки условию.','plane','Два непараллельных направления определяют направление плоскости.'),
 step('Существование: пункт 1','Найдите Q=b∩α.','Так как b не параллельна α, она пересекает её в единственной точке Q. Через Q в α проведите l∥c. Эта прямая не параллельна a, поэтому пересечёт a в P. Получена l=PQ, пересекающая a,b и параллельная c.','line','Две непараллельные прямые одной плоскости пересекаются.'),
 step('Единственность: пункт 2','Где должна лежать любая другая подходящая прямая?','Прямая, параллельная c и пересекающая a, обязана лежать в α. Если она пересекает b, то проходит через Q=b∩α. Через Q существует ровно одна прямая, параллельная c; это построенная PQ.','unique','Через точку проходит единственная прямая заданного направления.')],
 'Используйте плоскость через a, параллельную c. Условие о трёх направлениях заставляет b пересечь эту плоскость.',sourceparts=['1','2'])

# 4: construct a parallelepiped, a particular quadrangular prism.
m=unit_prism();m['points']={k:[2*v[0],v[1],1.5*v[2]] for k,v in m['points'].items()};m['labelNames']=['A','B','C','D','A1','B1','C1','D1'];view(m,'given','Данные прямые: AB, A₁D₁, CC₁',segments=[['A','B'],['A1','D1'],['C','C1']]);view(m,'bases','Две параллельные плоскости оснований',polygon=['A','B','C','D'],segments=[['A1','D1'],['C','C1']]);view(m,'projection','Проекция b на α вдоль c — прямая AD',segments=[['A1','D1'],['A','D'],['A','A1'],['D','D1']]);view(m,'base','Параллелограмм ABCD',polygon=['A','B','C','D']);view(m,'result','Три требуемых ребра',segments=[['A','B'],['A1','D1'],['C','C1']])
save('skew-lines',4,'Призма по трём скрещивающимся прямым','Даны три попарно скрещивающиеся прямые, не параллельные одной плоскости. Докажите, что существует четырёхугольная призма, три ребра которой лежат на данных прямых.','Построить такую призму.',m,[
 step('Плоскости оснований','Обозначьте прямые a,b,c.','Проведите α через a параллельно b и α′ через b параллельно α. Плоскости различны, иначе a,b были бы компланарны. Поскольку направление c не параллельно α, обозначим C=c∩α, C₁=c∩α′.','bases','Условие о трёх направлениях исключает параллельность c плоскости α.'),
 step('Спроецируем b','Рассмотрите плоскость через b, параллельную c.','Её пересечение с α обозначим b′. Прямая b′ параллельна b и является её проекцией на α вдоль c. Пусть A=a∩b′. Прямая b′ не параллельна a.','projection','Параллельные плоскости пересекаются третьей по параллельным прямым.'),
 step('Первое основание','Постройте через C две параллельные прямые.','Через C проведите прямую, параллельную b′, до пересечения с a в B; и прямую, параллельную a, до пересечения с b′ в D. Получен параллелограмм ABCD. Он невырожден: C не лежит ни на a, ни на b′, иначе две исходные прямые пересекались бы.','base','Через точку можно провести единственные прямые двух заданных непараллельных направлений.'),
 step('Призма','Перенесите основание на вектор CC₁.','Получим параллелепипед ABCDA₁B₁C₁D₁, то есть четырёхугольную призму. Ребро AB лежит на a; A₁D₁ — на b; CC₁ — на c. Значит, требуемая призма существует.','result','Параллельный перенос параллелограмма образует параллелепипед.')],
 'Достаточно построить параллелепипед. Возьмите первые два направления для плоскостей оснований, третье — для боковых рёбер.')

# 5: orthogonal projection normal to CN converts the problem into symmetry.
m=model({'A':[-3,1,0],'B':[2,3,0],'C':[0,0,0],'D':[0,0,4]},[['A','B'],['B','C'],['C','A'],['A','D'],['B','D'],['C','D']],[['A','B','C'],['A','B','D'],['B','C','D'],['C','A','D']]);at(m,'M','D','B',.5);at(m,'N','A','B',.5);at(m,'K','C','D',1/3)
u=vec(m['points']['N']);u/=np.linalg.norm(u)
for src,dst in [('A','P'),('B','Q'),('M','R')]:
 p=vec(m['points'][src]);addpoint(m,dst,p-np.dot(p,u)*u)
foot(m,'H','C','P','K');foot(m,'J','C','Q','K');m['labelNames']=['A','B','C','D','M','N','K'];view(m,'given','Сравниваем расстояния от CN до AM и BK',segments=[['C','N'],['A','M'],['B','K']]);view(m,'projection','Проекция на плоскость через CD, перпендикулярную CN',segments=[['A','P'],['B','Q'],['M','R'],['P','Q'],['C','D']],points=['R']);view(m,'centroid','K — центроид треугольника PQD',polygon=['P','Q','D'],segments=[['P','R'],['C','D']],points=['K']);view(m,'distance','Равные высоты CH и CJ',segments=[['P','K'],['Q','K'],['C','H'],['C','J']])
save('skew-lines',5,'Равные расстояния','В тетраэдре DABC ребро CD перпендикулярно ABC. M — середина DB, N — середина AB, CK:KD=1:2. Докажите, что прямая CN равноудалена от прямых AM и BK.','Доказать равенство расстояний от CN до AM и BK.',m,[
 step('Уберём направление CN','Спроецируйте фигуру на плоскость π через C, перпендикулярную CN.','Плоскость π содержит CD, так как CD⊥ABC. Обозначим проекции A,B,M через P,Q,R. Прямая CN проецируется в C; N также в C. Проекция сохраняет середины, поэтому C — середина PQ, а R — середина DQ.','projection','Ортогональная проекция сохраняет отношения на прямой, если она не проецируется в точку.'),
 step('Центроид в проекции','Почему P,R,K лежат на одной прямой?','В треугольнике PQD отрезки DC и PR — медианы. Их пересечение делит DC в отношении 2:1 от D. Поскольку DK:KC=2:1, этим пересечением является K. Поэтому проекция AM — прямая PR=PK; проекция BK — QK.','centroid','Медианы треугольника пересекаются в центре тяжести и делятся им в отношении 2:1.'),
 step('Плоская симметрия','Сравните прямоугольные треугольники PCK и QCK.','CP=CQ, CK — общий катет, CK⊥PQ. Треугольники PCK и QCK равны; их гипотенузы PK и QK симметричны относительно CK. Поэтому расстояния CH и CJ от C до этих прямых равны.','distance','Равенство прямоугольных треугольников по двум катетам; осевая симметрия сохраняет расстояния.'),
 step('Вернёмся в пространство','Почему плоские расстояния равны искомым?','Для любой точки X расстояние до CN равно длине от C до ортогональной проекции X на π. Значит, минимум этих расстояний по X∈AM равен расстоянию от C до PK; по X∈BK — от C до QK. Они равны, следовательно, d(CN,AM)=d(CN,BK).','given','Проекция на плоскость, перпендикулярную прямой, превращает расстояние до этой прямой в расстояние до точки.')],
 'Спроецируйте пространство перпендикулярно CN. Используйте то, что проекция N совпадёт с C, а проекции A и B будут симметричны относительно C.')

# 6: common perpendicular in the diagonal plane.
